// Convierte el webhook de Meta en un ítem por mensaje y uno por estado de entrega.
// Solo procesa eventos del número configurado en Config.phoneNumberId.
const cfg = $('Config').first().json;
const body = cfg.body || {};

// Tipos que el CRM guarda como archivo (ver MEDIA_LIMITS del CRM).
const MIME_PERMITIDOS = [
  'audio/ogg', 'audio/mpeg', 'audio/mp4', 'audio/aac', 'audio/amr',
  'image/jpeg', 'image/png', 'image/webp', 'application/pdf',
];
const baseMime = (mime) => String(mime || '').split(';')[0].trim().toLowerCase();

function normalizar(m, nombres) {
  const base = {
    evento: 'mensaje',
    telefono: m.from,
    waMessageId: m.id,
    fecha: new Date(Number(m.timestamp) * 1000).toISOString(),
    nombrePerfil: nombres[m.from] || null,
    tipo: 'TEXTO',
    texto: null,
    mediaId: null,
    mime: null,
  };
  const archivo = (tipo, media, texto) => {
    const mime = baseMime(media && media.mime_type);
    const guardable = media && media.id && MIME_PERMITIDOS.includes(mime);
    return { ...base, tipo, texto, mediaId: guardable ? media.id : null, mime: guardable ? mime : null };
  };

  switch (m.type) {
    case 'text':
      return { ...base, texto: m.text.body };
    case 'button':
      return { ...base, tipo: 'INTERACTIVO', texto: m.button.text };
    case 'interactive': {
      const r = m.interactive || {};
      const titulo = (r.button_reply && r.button_reply.title) || (r.list_reply && r.list_reply.title) || '[Respuesta interactiva]';
      return { ...base, tipo: 'INTERACTIVO', texto: titulo };
    }
    case 'image':
      return archivo('IMAGEN', m.image, m.image.caption || '[Imagen]');
    case 'sticker':
      return archivo('IMAGEN', m.sticker, '[Sticker]');
    case 'audio':
      return archivo('AUDIO', m.audio, '[Nota de voz]');
    case 'document': {
      const nombre = m.document.filename ? `[Documento: ${m.document.filename}]` : '[Documento]';
      return archivo('DOCUMENTO', m.document, m.document.caption ? `${nombre} ${m.document.caption}` : nombre);
    }
    case 'video':
      return { ...base, texto: m.video && m.video.caption ? `[Video] ${m.video.caption}` : '[Video]' };
    case 'location': {
      const l = m.location || {};
      const lugar = [l.name, l.address].filter(Boolean).join(', ');
      return { ...base, texto: `[Ubicación: ${l.latitude}, ${l.longitude}${lugar ? ` · ${lugar}` : ''}]` };
    }
    case 'contacts':
      return { ...base, texto: '[Compartió un contacto]' };
    default:
      // reaction, unsupported, system…: no ameritan respuesta.
      return null;
  }
}

const salida = [];
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    const v = change.value || {};
    const numero = v.metadata && String(v.metadata.phone_number_id);
    if (cfg.phoneNumberId && numero && numero !== String(cfg.phoneNumberId)) continue;

    const nombres = {};
    for (const c of v.contacts || []) nombres[c.wa_id] = (c.profile && c.profile.name) || null;

    for (const m of v.messages || []) {
      const item = normalizar(m, nombres);
      if (item) salida.push({ json: item });
    }
    for (const s of v.statuses || []) {
      if (['sent', 'delivered', 'read', 'failed'].includes(s.status)) {
        salida.push({ json: { evento: 'estado', waMessageId: s.id, estado: s.status } });
      }
    }
  }
}
return salida;

// Arma el cuerpo de POST /api/agente/conversaciones/mensajes para el entrante.
const msg = $('Desglosar evento').item.json;
const cuerpo = {
  telefono: msg.telefono,
  waMessageId: msg.waMessageId,
  direccion: 'ENTRANTE',
  tipo: msg.tipo,
  texto: msg.texto || undefined,
  fecha: msg.fecha,
};
if ($json.archivoOk === true && $json.ruta) {
  cuerpo.media = { ruta: $json.ruta, mime: msg.mime };
  if ($json.bytes) cuerpo.media.bytes = $json.bytes;
}
return { json: { ...msg, cuerpo } };

// Confirma la baja o la solicitud de supresión de datos (política de Dicampo).
const respuesta = $json.data;
const telefono = $('Preparar entrante').item.json.telefono;
const textos = {
  BAJA: 'Listo, no te enviaremos más mensajes comerciales. Si más adelante quieres retomar, aquí estamos.',
  ELIMINAR_DATOS:
    'Recibimos tu solicitud para eliminar tus datos. La atendemos en un plazo máximo de 10 días hábiles y te confirmaremos por este medio.',
};
return { json: { telefono, texto: textos[respuesta.palabraClave] || textos.BAJA } };

// Arma el mensaje para el agente: hora de Bogotá, ficha del CRM, historial y
// el bloque de mensajes nuevos que el cliente escribió de corrido.
const ctx = $('CRM · Contexto').item.json.data;
const msg = $('Preparar entrante').item.json;
const lead = ctx.lead;

const partes = Object.fromEntries(
  new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Bogota',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23', weekday: 'long',
  }).formatToParts(new Date()).map((p) => [p.type, p.value]),
);
const dias = { Monday: 'lunes', Tuesday: 'martes', Wednesday: 'miércoles', Thursday: 'jueves', Friday: 'viernes', Saturday: 'sábado', Sunday: 'domingo' };
const ahora = `${dias[partes.weekday] || partes.weekday} ${partes.year}-${partes.month}-${partes.day}, ${partes.hour}:${partes.minute} (America/Bogota, UTC-05:00)`;

const autores = { CLIENTE: 'Cliente', AGENTE_IA: 'David (tú)', ASESOR: 'Asesor' };
const texto = (m) => m.texto || (m.conArchivo ? '[archivo]' : '');
const pendientes = new Set(ctx.pendientes.map((m) => m.waMessageId));
const historial = ctx.mensajes
  .filter((m) => !pendientes.has(m.waMessageId))
  .map((m) => `${autores[m.autor] || m.autor}: ${texto(m)}`)
  .join('\n');
const nuevos = ctx.pendientes.map(texto).join('\n');

let ficha = 'No está registrado en el CRM (todavía no es lead).';
if (lead) {
  ficha = JSON.stringify({
    clientId: lead.cliente.id,
    codigo: lead.cliente.codigo,
    negocio: lead.cliente.nombreComercial || lead.cliente.razonSocial,
    tipo: lead.cliente.tipo,
    estado: lead.cliente.estado,
    contacto: lead.contacto ? lead.contacto.nombre : null,
    vendedor: lead.vendedor ? lead.vendedor.nombre : null,
    oportunidadAbierta: lead.oportunidadAbierta,
    ultimoPedido: lead.ultimoPedido,
    sedePrincipal: lead.sedePrincipal,
  }, null, 2);
}

const secciones = [
  `Fecha y hora: ${ahora}\nNombre en su perfil de WhatsApp: ${msg.nombrePerfil || 'desconocido'}`,
  `Ficha en el CRM:\n${ficha}`,
  ctx.estado.descartada
    ? `Ojo: antes se descartó por ${ctx.estado.descartada.motivo}. Si ahora califica, sigue el flujo normal.`
    : null,
  ctx.estado.resumen ? `Resumen previo: ${ctx.estado.resumen}` : null,
  `Conversación hasta ahora:\n${historial || '(es el primer contacto)'}`,
  `Mensajes nuevos del cliente (respóndelos juntos):\n${nuevos}`,
];
const prompt = secciones.filter(Boolean).join('\n\n');

return { json: { prompt, telefono: msg.telefono } };

// Convierte la salida del agente en uno o más mensajes de WhatsApp y arma la
// traza (herramientas y fuentes) que muestra la supervisión del CRM.
const r = $input.first().json;
const telefono = $('Armar prompt').first().json.telefono;

let texto = String(r.output || '').trim()
  .replace(/\*\*(.+?)\*\*/g, '*$1*')
  .replace(/^#{1,6}\s+/gm, '');
if (!texto) throw new Error('El agente no devolvió texto.');

const pasos = r.intermediateSteps || [];
const herramientas = [...new Set(pasos.map((p) => p.action && p.action.tool).filter(Boolean))];
const fuentes = [];
for (const p of pasos) {
  if (!p.action || p.action.tool !== 'buscar_conocimiento') continue;
  try {
    let obs = typeof p.observation === 'string' ? JSON.parse(p.observation) : p.observation;
    if (Array.isArray(obs)) obs = obs[0];
    if (obs && typeof obs.response === 'string') obs = JSON.parse(obs.response);
    const filas = (obs && obs.data && obs.data.resultados) || [];
    for (const f of filas) {
      fuentes.push({ titulo: [f.titulo, f.seccion].filter(Boolean).join(' · ') || f.fuente, similitud: f.similitud });
    }
  } catch (e) {
    // Una observación que no es JSON no impide responder.
  }
}

// "---" en una línea separa mensajes; WhatsApp admite 4.096 caracteres.
const LIMITE = 4096;
const mensajes = [];
for (const parte of texto.split(/\n\s*---+\s*\n/)) {
  let resto = parte.trim();
  while (resto.length > LIMITE) {
    let corte = resto.lastIndexOf('\n', LIMITE);
    if (corte < LIMITE / 2) corte = resto.lastIndexOf(' ', LIMITE);
    if (corte < LIMITE / 2) corte = LIMITE;
    mensajes.push(resto.slice(0, corte).trim());
    resto = resto.slice(corte).trim();
  }
  if (resto) mensajes.push(resto);
}

return mensajes.map((t, i) => ({
  json: { telefono, texto: t, traza: i === 0 ? { herramientas, fuentes } : {} },
}));

// El agente falló (modelo caído, tiempo agotado, salida vacía): el cliente
// recibe un mensaje de respaldo y la conversación pasa a un asesor.
const telefono = $('Armar prompt').first().json.telefono;
const e = $input.first().json;
const detalle = String((e.error && (e.error.message || e.error)) || e.message || 'Error sin detalle').slice(0, 4000);
return [{
  json: {
    telefono,
    texto: 'Disculpa, se me presentó un inconveniente. Ya le aviso a un asesor de Dicampo para que te escriba en breve.',
    detalle: `El agente IA no pudo responder: ${detalle}`,
  },
}];
